\item[S2] Mladen Bestvina and Noel Brady, Morse theory and finiteness properties of groups, Inventiones Mathematicae 129 (1997), 445-470. \url{https://doi.org/10.1007/s002220050168}. Bibliographic information imported from the supplied record.

\item[S3] James Howie, Bestvina--Brady groups and the plus construction, Mathematical Proceedings of the Cambridge Philosophical Society 127 (1999), 487-493. \url{https://doi.org/10.1017/S0305004199003928}. Bibliographic information imported from the supplied record.

\item[S4] A. Adem and I. Hambleton, Minimal Euler characteristics for even-dimensional manifolds with finite fundamental group, Forum of Mathematics, Sigma 11 (2023), e24. \url{https://doi.org/10.1017/fms.2023.18}. Bibliographic information imported from the supplied record.

\item[R1] M. Bestvina and N. Brady, Morse theory and finiteness properties of groups, Inventiones Mathematicae 129 (1997), primary paper.
\url{https://people.math.osu.edu/davis.12/courses/8800-20/Bestvina-Brady.pdf}.
\end{itemize}

